import logging
from typing import Union

from pysnmp.proto import rfc1902

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import BadPortNumber

from .snmp import SnmpPdu


class SWH(SnmpPdu):
    """Class provides attributes and private methods to manage a PDU of type SWH."""

    NO_ACTION_OUTLETS_STATUS = ("5", "5", "5", "5", "5", "5", "5", "5")

    def __init__(self, host: str, timeout: Union[float, int] = 20, community: str = "public") -> None:
        """
        :param string host:     IP address or domain name of SWH device.
        :param float timeout:   Maximum number of seconds to wait for expected pdu outlet status.
        :param community:       Community string used by SNMPv1/2.
        """
        super().__init__(host, timeout, community=community)

        self._version = 0
        self._key = ".1.3.6.1.4.1.17420.1.2.9.1.13.0"

    def get_port_status(self, port):
        logging.info(f"SNMP: Fetching status of port: {port}")
        snmp_msg = self._build_snmp_oid(port=port)
        cmd_output = self._execute_get_cmd(snmp_msg)
        port_value = self._octetstring_to_list(cmd_output)[port - 1]
        return self._reversed_port_settings[port_value]

    @property
    def _port_setting(self):
        return {DeviceStatus.OFF: "0", DeviceStatus.ON: "1"}

    def _get_oid_value(self, value):
        return rfc1902.Integer(self._port_setting[value])

    def _build_snmp_oid(self, port):
        # This PDU has an octet string on the OID specified in self._key.
        # The individual ports seem to be unaccessible directly, although we
        # couldn't find it. We couldn't find correct MIB file for this PDU, SNMP
        # walks don't work, and the SKU seems to be a no-name reselled by
        # different manufacturers.
        return self._key

    def _octetstring_to_list(self, outlets_value):
        return outlets_value.split(",")

    def _list_to_octetstring(self, outlets_value_list):
        return rfc1902.OctetString(",".join(outlets_value_list))

    def _set_port_status(self, port, status):
        snmp_msg = self._build_snmp_oid(port=port)
        ports_value = self._set_oid_value(port, status)
        logging.info(f"SNMP: Setting port to {status}: {port}")
        self._execute_set_cmd(ports_value, snmp_msg)

    def _execute_set_cmd(self, value, snmp_msg):
        self._execute_cmd(self._cmdgen.setCmd, (snmp_msg, value))

    def _set_oid_value(self, port, status):
        try:
            outlets_value = list(SWH.NO_ACTION_OUTLETS_STATUS)
            outlets_value[port - 1] = self._port_setting[status]
            return self._list_to_octetstring(outlets_value)
        except IndexError:
            raise BadPortNumber("Port %d is out of range" % port)
